INSERT INTO `edu_teacher`(`id`,`name`,`intro`,`career`,`level`,`avatar`,`sort`,`is_deleted`,`gmt_create`,`gmt_modified`) VALUES
('1','沃伦·巴菲特','Warren Buffett（金融投资）· 伯克希尔·哈撒韦董事长','价值投资的开创者与实践者，1956年接手伯克希尔后以「安全边际、能力圈、护城河」三大原则构建了半个世纪的投资业绩。1957年致股东信中提出「人生就像滚雪球，重要的是找到很湿的雪和很长的坡」。1998年佛罗里达大学演讲系统阐述了他的投资哲学，被公认为价值投资的圣经。',2,'/photo/teacher/01.jpg',1,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('2','查理·芒格','Charlie Munger（金融投资）· 伯克希尔副董事长','巴菲特的合伙人，被尊为「人类误判心理学」大师。他提出并运用多学科思维模型格栅（mental models），强调「要成为一个有智慧的人，必须掌握多个学科的核心基本真理」。1995年哈佛大学演讲《人类误判心理学》系统列出 25 种心理倾向，影响了整个投资界的认知框架。',2,'/photo/teacher/02.jpg',2,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('3','本杰明·格雷厄姆','Benjamin Graham（金融投资）· 「证券分析之父」','哥伦比亚大学经济学教授，《证券分析》（1934）与《聪明的投资者》（1949）的作者，现代证券分析学的奠基人。他提出「安全边际」原则与「市场先生」寓言，定义了股债平衡的投资组合理论，被巴菲特称为「投资界圣经的两位作者之一」。',1,'/photo/teacher/03.jpg',3,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('4','罗伯特·席勒','Robert Shiller（金融投资）· 耶鲁大学经济学教授 · 2013年诺贝尔经济学奖得主','行为金融学代表人物，耶鲁大学 ECON 252《Financial Markets》主讲教授，该课成为全球最受欢迎的经济学公开课之一。他用「金融时间序列的波动性远大于实际变化」的研究揭示了泡沫的统计特征，著有《非理性繁荣》，并于 2013 年获诺贝尔经济学奖。',2,'/photo/teacher/04.jpg',4,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('5','瑞·达利欧','Ray Dalio（金融投资）· 桥水基金创始人','1975年创办桥水基金，将其打造为全球规模最大的对冲基金之一。他的《经济机器是如何运转的》用 30 分钟讲清信用、债务周期与去杠杆三台引擎，是全球播放量最高的经济学讲解之一。著有《原则》《债务危机》，主张用「可信度加权」的决策方式处理复杂世界。',1,'/photo/teacher/05.jpg',5,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('6','霍华德·马克斯','Howard Marks（金融投资）· 橡树资本联合创始人 · 哥伦比亚商学院客座教授','以「周期思维」闻名的机构投资人，著有《投资最重要的事》《周期》。他强调投资的胜负关键不在于预测未来，而在于理解当前所处的周期位置，并提出「风险的本质是永久性资本损失」这一业界共识。',1,'/photo/teacher/06.jpg',6,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('7','阿斯瓦特·达摩达兰','Aswath Damodaran（金融投资）· 纽约大学斯特恩商学院教授','公司估值领域的世界级学者，著有《投资估值》，被业界称为「估值教父」。他每年在纽约大学开设完整的股权估值课程并全程公开录像，配套免费电子表格，是全球最系统化的估值方法论训练体系。',1,'/photo/teacher/07.jpg',7,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('8','吉姆·西蒙斯','Jim Simons（金融投资）· 文艺复兴科技创始人 · 量化投资先驱','数学家出身，创办文艺复兴科技并以「打败市场」的量化策略管理百亿级资产，被《财富》评为对冲基金史上最伟大的管理人。他的核心思想是用数据、模型与统计规律替代主观判断，定义了现代量化投资的技术路线。',1,'/photo/teacher/08.jpg',8,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('9','杰夫·迪恩','Jeff Dean（IT工程）· Google 首席科学家 · 大规模系统架构先驱','主导设计了 MapReduce、BigTable、TensorFlow 与 Google Brain，是 Transformer 论文的共同作者之一。他定义了「大规模计算系统」的设计范式，用「把问题规模放大 1000 倍再解决」的思路，塑造了整个云计算与 AI 基础设施的形态。',2,'/photo/teacher/09.jpg',9,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('10','布莱恩·克尼汉','Brian Kernighan（IT工程）· 普林斯顿大学教授 ·《算法导论》作者之一','与 Donald Knuth、Robert Sedgewick 共同编写了计算机科学领域最经典的《算法导论》（CLRS）。他发明了 AWK 语言与「K&R C」编程风格，主张算法设计应兼顾优雅与效率，其编程范式影响了数代工程师。',1,'/photo/teacher/10.jpg',10,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('11','詹姆斯·高斯林','James Gosling（IT工程）· Java 语言创造者 · Sun 公司副总裁','在 Sun 公司工作期间主导设计并实现 Java 语言，被称为「Java 之父」。他推动 Java 确立为「一次编写，到处运行」的跨平台语言，并主导了 JVM 规范，使 Java 成为企业级后端开发的标准语言之一。',1,'/photo/teacher/11.jpg',11,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('12','安德烈·卡帕斯','Andrej Karpathy（IT工程）· 前特斯拉 AI 负责人 · 斯坦福 CS231n 主讲','斯坦福大学 CS231n《计算机视觉中的深度学习》主讲教师，课程录像在 YouTube 播放量超过百万。他提炼出的「神经网络七步训练法」与反向传播的直觉化讲解，被公认为深度学习入门最清晰的教学体系。',1,'/photo/teacher/12.jpg',12,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('13','埃里克·施密特','Eric Schmidt（IT工程）· 前 Google 首席执行官','2001—2011 年执掌 Google，完成了从搜索引擎公司到全球最大科技公司的转型，主导收购 YouTube、Android 并将 Google 推向云与 AI 战略。他提出「企业要在 AI 时代赢，关键是重新定义组织与人才密度」，并推动 Google 设立 AI 伦理委员会。',1,'/photo/teacher/13.jpg',13,0,'2026-10-22 10:00:00','2026-10-22 10:00:00'),
('14','本·斯托伊卡','Ben Stoica（IT工程）· 加州大学伯克利分校教授 ·《Designing Data-Intensive Applications》作者','分布式系统与数据库领域的世界级学者，ACM Fellow。他主讲的伯克利 CS186 数据库系统课与 CS162 操作系统课以「真实工程问题驱动」著称，其著作《数据密集型应用系统设计》已成为后端架构师的必读经典。',1,'/photo/teacher/14.jpg',14,0,'2026-10-22 10:00:00','2026-10-22 10:00:00');
