INSERT INTO `edu_course_description`(`id`,`description`,`gmt_create`,`gmt_modified`) VALUES
('1','耶鲁大学 Robert Shiller 名下的经典经济学公开课，23 讲完整覆盖金融市场的本质、风险与收益、行为金融学、衍生品定价与金融危机的形成机制。席勒用「市场先生」寓言和大量真实数据把抽象的金融理论讲得清晰可感，是理解现代金融体系的最佳第一课。<br/><br/>课程来源：Yale Courses 官方播放列表 · 23 讲全片','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('2','纽约大学斯特恩商学院 Aswath Damodaran 教授的完整股权估值课程，从「估值为何重要」讲到内在价值、相对估值、私募公司估值、实物期权与价值提升五大板块，每一场都配可下载的讲义与电子表格。适合想把「感觉贵不贵」变成可计算结论的所有人。<br/><br/>课程来源：NYU Stern 达摩达兰估值课 · 26 场次公开录像','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('3','汇集巴菲特与查理·芒格历年访谈与股东大会精华 24 集，从「能力圈」「护城河」「安全边际」到「集中投资」与「持有期限」，完整呈现价值投资的方法论骨架。适合想建立自己的投资决策框架、而不是靠消息选股的读者。<br/><br/>课程来源：B 站巴菲特与芒格访谈合集 · 24 集','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('4','对外经济贸易大学张新民教授的《财务报表分析》必修课全 32 讲，从「财报对老板和高管很重要」讲到如何从利润表、资产负债表、现金流量表交叉验证企业的真实盈利能力，配套长安汽车等真实案例拆解。<br/><br/>课程来源：对外经贸大学张新民教授公开课 · 全 32 讲','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('5','桥水基金创始人瑞·达利欧的 42 集投资智慧合集，以《经济机器是如何运转的》开篇，系统讲解信用创造、债务周期、央行政策、黄金与货币秩序，以及他创立并写入《原则》的方法论体系。<br/><br/>课程来源：B 站瑞·达利欧投资智慧合集 · 42 集','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('6','Quantopian 公开的 56 讲量化投资课程，从 Python 工具链、统计推断一路讲到因子模型、风险约束组合优化、VaR/CVaR、协整与配对交易、期货与多因子实盘复盘。是被量化圈公认为最系统的入门到进阶路线。<br/><br/>课程来源：Quantopian 公开课系列 · 56 讲','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('7','MIT 6.006《算法导论》官方课程完整播放列表，24 讲正课覆盖排序、哈希、BFS/DFS、最短路、动态规划与复杂度分析，并附 14 节习题讲解课。算法工程师与后端面试准备者的标准教材级训练。<br/><br/>课程来源：MIT OCW 6.006 官方播放列表 · 24 讲 + 习题课','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('8','伯克利 Full Stack Deep Learning 课程 2022 版完整录像，9 讲覆盖课程愿景、开发基础设施、测试排障、数据管理、模型部署、持续学习、基础大模型、团队管理与伦理，配套 8 个动手实验。这是把模型变成产品的唯一系统化路径。<br/><br/>课程来源：UC Berkeley Full Stack Deep Learning 2022 · 9 讲 + 8 实验','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('9','以 Berkeley CS186 数据库系统课的方法论为主线，配合 B 站 199 集 MySQL 全系列实战教程，从关系模型、SQL 执行计划、B+ 树索引、事务隔离、MVCC 一路讲到主从复制与分库分表，理论与工程双线并进。<br/><br/>课程来源：B 站 MySQL 全系列教程 · 199 集','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('10','以 Java 之父高斯林所奠定的语言设计哲学为线索，配套 B 站 716 集 Java 基础全集，系统讲解语法基础、面向对象、集合、IO、多线程、反射与泛型，为后续的 Spring 微服务与高并发打下地基。<br/><br/>课程来源：B 站 Java 基础全集 · 716 集','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('11','以 Google 前端大规模工程实践为参照，配套 B 站 71 集 Vue3 + TypeScript 实战教程，覆盖组合式 API、响应式原理、组件通信、Vite 构建、状态管理 Pinia 与前后端联调，形成可交付的企业级前端工程能力。<br/><br/>课程来源：B 站 Vue3 全栈实战 · 71 集','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('12','斯坦福 CS231n《计算机视觉中的深度学习》官方录像全集，卡帕斯用「从零手写训练循环」的方式讲透 CNN 架构、训练技巧与迁移学习，并配 3 个课程作业（线性分类器、CNN、从头训练）作为动手验收。<br/><br/>课程来源：Stanford CS231n 官方播放列表 · Karpathy 主讲','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('13','吴恩达与 DeepLearning.AI 联合出品的机器学习专项课程官方播放列表，涵盖监督学习、进阶学习算法、无监督学习与强化学习三大板块，是全球完课人数最多的机器学习系统课，配 Python + scikit-learn + TensorFlow 实操。<br/><br/>课程来源：DeepLearning.AI 官方播放列表 · 专项全三门','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('14','伯克利 FSDL 2021 版本的完整 18 个视频，主题涵盖项目管理、基础设施、测试、迭代、监控、模型部署、持续学习与数据管理。相比 2022 版更适合作为 MLOps 流程的入门第一课，讲解节奏更缓、案例更完整。<br/><br/>课程来源：Full Stack Deep Learning 2021 · 18 个视频','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('15','以 Google 大规模服务化经验为参照，配套 B 站 150 集 Spring Cloud 微服务实战教程，讲解服务拆分边界、注册发现、配置中心、网关、熔断限流、链路追踪与容器化部署，构建可上生产的服务治理体系。<br/><br/>课程来源：B 站 Spring Cloud 微服务实战 · 150 集','2026-10-22 10:00:00','2026-10-22 10:00:00'),
('16','配套 B 站 178 集 Hadoop3.x 实战教程，系统讲解大数据的 5V 特征与生态体系、HDFS 存储原理、YARN 资源调度、MapReduce 编程模型，并以 Spark 作为迭代计算与实时流处理的落地路径，串起离线数仓到实时决策的完整链路。<br/><br/>课程来源：B 站 Hadoop3.x 大数据实战 · 178 集','2026-10-22 10:00:00','2026-10-22 10:00:00');
